const FLAME_TEX = flameTexture();

function buildTorches() {
  for (const side of [-1, 1]) {
    for (let z = -18; z <= 30; z += 8) {
      const x = side * 11.2;
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.13, 3.1, 8), woodMat);
