    b.castShadow = true; city.add(b);
    const d = new THREE.Mesh(new THREE.SphereGeometry(3.2, 14, 8, 0, Math.PI * 2, 0, Math.PI / 2), dome);
    d.position.set(x, hgt, -6 - (i % 3) * 5); city.add(d);
