    shaft.position.set(x, 11, z); shaft.castShadow = true; city.add(shaft);
    const balcony = new THREE.Mesh(new THREE.CylinderGeometry(1.5, 1.5, 0.5, 10), dome);
    balcony.position.set(x, 17, z); city.add(balcony);
